/**
 * Plain-text rendition conformance: toText() output must match the
 * reference implementation byte-for-byte.
 *
 * Expected text generated by tools/transform-oracle.php --text
 * (full default configuration: typography + hyphenation on; emoticons off,
 * the reference default - the emoticon-on.txt fixture is the same source
 * generated with --emoticon). Soft hyphens and non-breaking spaces are
 * stripped by the text renderer itself.
 */

import { Syntax } from "../src/Syntax.js";
import { renderConformance } from "./helpers/render-conformance.js";

/**
 * Sources with known typography divergences of the @gryphoon/texy library
 * (same as render-typo.test.js; hyphenation output is hidden by the text
 * renderer, but the underlying text runs still differ for edge-cases).
 */
const knownDivergences = new Set(["edge-cases"]);

renderConformance({
  suite: "conformance: plain-text rendition matches the reference implementation",
  fixturesDir: "text",
  extension: ".txt",
  convert: (texy, source) => texy.toText(source),
  configure: (texy, name) => {
    if (name === "emoticon-on") {
      texy.allowed[Syntax.Emoticon] = true; // only this fixture was generated with --emoticon
    }
  },
  knownDivergences,
});
